--
-- Table structure for table `students`
--

DROP TABLE IF EXISTS `students`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `students` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `trade` varchar(150) DEFAULT NULL,
  `passing_year` varchar(50) DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL,
  `hsc` decimal(5,2) DEFAULT NULL,
  `ssc` decimal(5,2) DEFAULT NULL,
  `gender` varchar(20) DEFAULT NULL,
  `institute_id` int(11) DEFAULT NULL,
  `iti` varchar(255) DEFAULT NULL,
  `mobile` varchar(50) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `dob` varchar(50) DEFAULT NULL,
  `experience` varchar(100) DEFAULT NULL,
  `previous_company` varchar(255) DEFAULT NULL,
  `preferred_location` varchar(255) DEFAULT NULL,
  `expected_salary` varchar(100) DEFAULT NULL,
  `computer_knowledge` varchar(100) DEFAULT NULL,
  `languages_known` varchar(255) DEFAULT NULL,
  `driving_licence` varchar(50) DEFAULT NULL,
  `registration_no` varchar(100) DEFAULT NULL,
  `result` varchar(50) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'Active',
  `job_role` varchar(150) DEFAULT NULL,
  `father_name` varchar(255) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `blood_group` varchar(20) DEFAULT NULL,
  `parents_mobile` varchar(50) DEFAULT NULL,
  `aadhaar_no` varchar(50) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_students_name` (`name`),
  KEY `idx_students_trade` (`trade`),
  KEY `idx_students_passing_year` (`passing_year`),
  KEY `idx_students_district` (`district`),
  KEY `idx_students_gender` (`gender`),
  KEY `idx_students_iti` (`iti`),
  KEY `idx_students_institute_id` (`institute_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1319 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

